class Registry:
    """Registry for plugin callables."""

    def __init__(self):
        self._plugins = {}

    def register(self, name, fn):
        """Register a callable under a name. Raises ValueError if duplicate."""
        if name in self._plugins:
            raise ValueError(f"Plugin already registered for name {name!r}")
        self._plugins[name] = fn

    def get(self, name):
        """Look up a plugin by name. Raises KeyError if unknown."""
        return self._plugins[name]

    def run(self, name, *args):
        """Run the plugin registered under name with the given arguments."""
        fn = self.get(name)
        return fn(*args)


registry = Registry()

__all__ = ["registry"]
